<?php
require __DIR__.'/../app/bootstrap.php';
\Portal\Auth::requireRoles([2,3,4,5,7]);
require __DIR__.'/src/Inventory.php';
mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);
$inventory=new \Inventory\Inventory($con);$e=static fn($v)=>\Portal\Html::escape((string)$v);
$error='';$ready=true;$pageTitle='Inventory';$portalNavigationPath='/dashboard/inventory/index.php';
try{$inventory->rows('SELECT item_id FROM portal_inventory_settings LIMIT 1');$inventory->rows('SELECT id FROM portal_inventory_movements LIMIT 1');}catch(Throwable $ex){$ready=false;}
if($ready&&($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 try{
  if(!\Portal\Csrf::valid($_POST['_csrf']??null))throw new InvalidArgumentException('Your session expired. Refresh and try again.');
  $action=$_POST['action']??'';
  if($action==='move'){$inventory->move([$_POST],(string)($_POST['kind']??''),(string)($_POST['request_key']??''),$portalUser->id);}
  elseif($action==='csv_preview'){
   $file=$_FILES['csv']??[];if(($file['error']??-1)!==UPLOAD_ERR_OK||($file['size']??0)>262144)throw new InvalidArgumentException('Use a CSV smaller than 256 KB.');
   $h=fopen($file['tmp_name'],'r');if(fgetcsv($h)!==['item_id','quantity','reason'])throw new InvalidArgumentException('CSV header must be item_id,quantity,reason.');
   $lines=[];while(($r=fgetcsv($h))!==false){if(count($r)!==3||count($lines)>=200)throw new InvalidArgumentException('Use three columns and at most 200 rows.');$lines[]=['item_id'=>\Inventory\Inventory::number($r[0]),'quantity'=>\Inventory\Inventory::number($r[1]),'reason'=>$r[2]];}fclose($h);
   if(!in_array($_POST['kind']??'',['receive','issue','count'],true)||!$lines)throw new InvalidArgumentException('Select an operation and provide rows.');
   $_SESSION['inventory_preview']=['lines'=>$lines,'kind'=>$_POST['kind'],'key'=>bin2hex(random_bytes(32))];
  }elseif($action==='csv_commit'){
   $preview=$_SESSION['inventory_preview']??null;
   if(!$preview||!hash_equals($preview['key'],(string)($_POST['request_key']??'')))throw new InvalidArgumentException('Preview expired. Upload again.');
   $inventory->move($preview['lines'],$preview['kind'],$preview['key'],$portalUser->id);unset($_SESSION['inventory_preview']);
  }elseif(in_array($action,['item','category'],true)){$inventory->catalog($_POST);}
  else throw new InvalidArgumentException('Unknown action.');
  $_SESSION['msg']=$action==='csv_preview'?'Review the import below before applying it.':'Inventory saved.';$_SESSION['msg_type']='success';header('Location: /dashboard/inventory/index.php');exit;
 }catch(InvalidArgumentException $ex){$error=$ex->getMessage();}catch(Throwable $ex){error_log('Inventory: '.$ex->getMessage());$error='Nothing was saved. Check the server error log or ask your administrator.';}
}
$items=[];$categories=[];$history=[];$edit=[];$q=is_string($_GET['q']??null)?trim($_GET['q']):'';
if($ready){
 try{
  $categories=$inventory->rows('SELECT category_id,category_name FROM sc_stock_categories ORDER BY category_name');
  $items=$inventory->rows('SELECT i.*,c.category_name,COALESCE(s.reorder_level,0) reorder_level,COALESCE(s.archived,0) archived FROM sc_stock_items i LEFT JOIN sc_stock_categories c ON c.category_id=i.category_id LEFT JOIN portal_inventory_settings s ON s.item_id=i.item_id WHERE i.item_name LIKE ? ORDER BY i.item_name LIMIT 501','s',['%'.$q.'%']);
  if(isset($_GET['item']))$edit=$inventory->rows('SELECT i.*,COALESCE(s.reorder_level,0) reorder_level,COALESCE(s.archived,0) archived FROM sc_stock_items i LEFT JOIN portal_inventory_settings s ON s.item_id=i.item_id WHERE i.item_id=?','i',[(int)$_GET['item']])[0]??[];
  $history=$inventory->rows('SELECT m.*,i.item_name,u.fullname FROM portal_inventory_movements m LEFT JOIN sc_stock_items i ON i.item_id=m.item_id LEFT JOIN users_tbl u ON u.id=m.actor_id ORDER BY m.id DESC LIMIT 100');
 }catch(Throwable $ex){error_log('Inventory read: '.$ex->getMessage());$ready=false;$error='Inventory schema needs attention. Ask your administrator to check the setup.';}
}
require __DIR__.'/../header.php';
?>
<link rel="stylesheet" href="<?= $e(\Portal\Html::asset('inventory/assets/inventory.css')) ?>">
<div class="inventory-page"><header class="inventory-heading"><div><p class="inventory-eyebrow">OPERATIONS / STOCK CONTROL</p><h1>Inventory</h1><p>A clear record of what you hold, receive, and use.</p></div><a class="btn btn-primary" href="#movement">Record movement</a></header>
<?php if($error):?><div class="alert alert-danger" role="alert"><?= $e($error) ?></div><?php endif; ?>
<?php if(!$ready):?><div class="alert alert-warning">Inventory setup is incomplete. Your administrator needs to follow the inventory installation guide before using this screen.</div><?php else: ?>
<nav class="inventory-tabs" aria-label="Inventory sections"><a href="#catalog">Stock on hand</a><a href="#movement">Receive / use / count</a><a href="#item">Item details</a><a href="#history">Movement history</a><a href="#import">CSV import</a></nav>
<section class="inventory-panel" id="catalog"><div class="inventory-panel-heading"><div><h2>Stock on hand</h2><p>Current balances and reorder thresholds</p></div><form method="get"><label class="visually-hidden" for="inventory-search">Search items</label><input id="inventory-search" name="q" value="<?= $e($q) ?>" placeholder="Search item name"><button class="btn btn-outline-secondary">Search</button></form></div>
<div class="inventory-table"><table><thead><tr><th>Item</th><th>Category</th><th>On hand</th><th>Reorder at</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach(array_slice($items,0,500) as $row): ?><tr><td><strong><?= $e($row['item_name']) ?></strong><small>#<?= (int)$row['item_id'] ?> · <?= $e($row['supplier']??'') ?></small></td><td><?= $e($row['category_name']??'Uncategorised') ?></td><td class="inventory-quantity"><?= (int)$row['qty_on_hand'] ?></td><td><?= (int)$row['reorder_level'] ?></td><td><span class="inventory-status"><?= $row['archived']?'Archived':((int)$row['qty_on_hand']===0?'Out of stock':((int)$row['qty_on_hand']<=(int)$row['reorder_level']?'Reorder':'Available')) ?></span></td><td><a href="?item=<?= (int)$row['item_id'] ?>#item">Manage</a></td></tr><?php endforeach; ?>
<?php if(!$items):?><tr><td colspan="6">No matching stock items. Add an item below to get started.</td></tr><?php endif; ?></tbody></table></div><?php if(count($items)>500):?><p>Showing 500 items. Narrow your search to find other items.</p><?php endif; ?></section>
<div class="inventory-columns"><section class="inventory-panel" id="movement"><h2>Record a stock movement</h2><p>Receipts add stock. Usage removes it. A stocktake sets the counted balance.</p><form method="post"><?= \Portal\Csrf::field() ?><input type="hidden" name="action" value="move"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(32)) ?>">
<label>Item ID<input name="item_id" type="number" min="1" value="<?= $edit?(int)$edit['item_id']:'' ?>" required></label><label>Movement<select name="kind"><option value="receive">Receive stock</option><option value="issue">Record usage / sale</option><option value="count">Stocktake — actual counted quantity</option></select></label><label>Quantity<input name="quantity" type="number" min="0" max="999999999" required></label><label>Reason / reference<input name="reason" maxlength="255" placeholder="Delivery reference, usage reason or count reference" required></label><button class="btn btn-primary">Save movement</button></form></section>
<section class="inventory-panel" id="item"><h2><?= $edit?'Edit item':'Add an item' ?></h2><p>Create items at zero, then receive the opening stock with a reference.</p><form method="post"><?= \Portal\Csrf::field() ?><input type="hidden" name="action" value="item"><input type="hidden" name="item_id" value="<?= (int)($edit['item_id']??0) ?>"><label>Item name<input name="item_name" value="<?= $e($edit['item_name']??'') ?>" maxlength="100" required></label><label>Category<select name="category_id" required><option value="">Select category</option><?php foreach($categories as $c):?><option value="<?= (int)$c['category_id'] ?>" <?= (int)($edit['category_id']??0)===(int)$c['category_id']?'selected':'' ?>><?= $e($c['category_name']) ?></option><?php endforeach; ?></select></label>
<div class="inventory-fields"><?php foreach(['cost_price'=>'Unit cost','retail_price'=>'Retail price','reorder_level'=>'Reorder threshold'] as $key=>$label):?><label><?= $label ?><input type="number" name="<?= $key ?>" min="0" step="<?= $key==='reorder_level'?'1':'0.01' ?>" value="<?= $e($edit[$key]??'0') ?>" required></label><?php endforeach; ?></div><label>Supplier<input name="supplier" value="<?= $e($edit['supplier']??'') ?>" maxlength="100"></label><?php if($edit):?><label><input type="checkbox" name="archived" <?= !empty($edit['archived'])?'checked':'' ?>> Archive item (balance must be zero)</label><?php endif; ?><button class="btn btn-primary">Save item</button> <a href="index.php#item">New item</a></form>
<details><summary>Manage categories</summary><form method="post"><?= \Portal\Csrf::field() ?><input type="hidden" name="action" value="category"><label>Category<select name="category_id"><option value="0">Create new category</option><?php foreach($categories as $c):?><option value="<?= (int)$c['category_id'] ?>">Rename <?= $e($c['category_name']) ?></option><?php endforeach; ?></select></label><label>Category name<input name="category_name" maxlength="100" required></label><button class="btn btn-outline-secondary">Save category</button></form></details></section></div>
<section class="inventory-panel" id="import"><h2>Import stock movements</h2><p>CSV columns: <code>item_id,quantity,reason</code>. One row per item, up to 200 rows. Review before applying; all rows succeed together.</p><form method="post" enctype="multipart/form-data" class="inventory-import"><?= \Portal\Csrf::field() ?><input type="hidden" name="action" value="csv_preview"><label>Operation<select name="kind"><option value="receive">Receive</option><option value="issue">Usage</option><option value="count">Stocktake</option></select></label><label>CSV file<input type="file" name="csv" accept=".csv,text/csv" required></label><button class="btn btn-outline-secondary">Preview import</button></form>
<?php if(isset($_SESSION['inventory_preview'])):$preview=$_SESSION['inventory_preview'];?><h3>Review <?= $e($preview['kind']) ?> import</h3><div class="inventory-table"><table><thead><tr><th>Item ID</th><th>Quantity</th><th>Reason</th></tr></thead><tbody><?php foreach($preview['lines'] as $line):?><tr><td><?= (int)$line['item_id'] ?></td><td><?= (int)$line['quantity'] ?></td><td><?= $e($line['reason']) ?></td></tr><?php endforeach; ?></tbody></table></div><form method="post"><?= \Portal\Csrf::field() ?><input type="hidden" name="action" value="csv_commit"><input type="hidden" name="request_key" value="<?= $e($preview['key']) ?>"><button class="btn btn-primary">Apply these movements</button></form><?php endif; ?></section>
<section class="inventory-panel" id="history"><h2>Movement history</h2><p>The latest 100 movements. Corrections should be recorded as new stocktakes with a reason.</p><div class="inventory-table"><table><thead><tr><th>When</th><th>Item</th><th>Movement</th><th>Before</th><th>Change</th><th>After</th><th>Recorded by / reason</th></tr></thead><tbody><?php foreach($history as $m):?><tr><td><?= $e($m['created_at']) ?></td><td><?= $e($m['item_name']??('#'.$m['item_id'])) ?></td><td><?= $e($m['kind']) ?></td><td><?= (int)$m['quantity_before'] ?></td><td><?= (int)$m['delta'] ?></td><td><?= (int)$m['quantity_after'] ?></td><td><?= $e($m['fullname']??'Migration') ?><small><?= $e($m['reason']) ?></small></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php endif; ?></div><?php require __DIR__.'/../footer.php'; ?>
